24:    --gutter: max(16px, calc((100vw - 1120px) / 2));
44:    padding: 18px var(--gutter); background: linear-gradient(var(--bg), rgba(11, 12, 14, 0));
79:    padding: 88px var(--gutter) 72px; opacity: 0; pointer-events: none; will-change: opacity, transform;
87:  .sub { color: var(--muted); font-size: clamp(17px, 2vw, 21px); max-width: 560px; margin: 0 0 32px; }
111:  .cap { color: var(--muted); font-size: clamp(16px, 1.8vw, 19px); margin: 18px 0 0; max-width: 520px; }
114:  .h2 { margin: 0 0 22px; font-size: clamp(26px, 4.2vw, 52px); line-height: 1.02; letter-spacing: -.02em; font-stretch: 108%; font-weight: 800; max-width: 820px; }
116:  .diff { max-width: 780px; border: 1px solid var(--rule); border-radius: 12px; background: rgba(20, 22, 26, .92); overflow: hidden; }
136:  .rail { position: absolute; right: var(--gutter); top: 50%; transform: translateY(-50%); transition: opacity .3s; list-style: none; margin: 0; padding: 0; display: grid; gap: 14px; font: 12px var(--mono); }
143:  .progress { position: absolute; left: var(--gutter); right: var(--gutter); bottom: 24px; display: flex; align-items: center; gap: 14px; font: 12px var(--mono); color: var(--muted); }
158:  .wrap { padding: 0 var(--gutter); }
  @keyframes marquee { to { transform: translateX(-50%); } }

  /* regular sections after the story */
  .wrap { padding: 0 var(--gutter); }
  section.block { padding: 96px 0 0; }
  .lede { font-size: clamp(26px, 4vw, 44px); font-weight: 800; letter-spacing: -.02em; line-height: 1.05; font-stretch: 108%; margin: 0 0 32px; max-width: 760px; }

  .cards { display: grid; grid-template-columns: repeat(3, 1fr); gap: 12px; }
  footer { margin: 120px var(--gutter) 0; padding: 28px 0 40px; border-top: 1px solid var(--rule); color: var(--muted); font-size: 14px; display: flex; justify-content: space-between; gap: 12px; flex-wrap: wrap; }

  .reveal { opacity: 0; transform: translateY(16px); transition: opacity .6s ease, transform .6s ease; }
  .reveal.in { opacity: 1; transform: none; }

  @media (max-width: 860px) {
    .rail { display: none; }
    .cards { grid-template-columns: 1fr; }
  }
  @media (max-width: 480px) {
    .scene { padding: 76px 16px 64px; }
    .diff-body { font-size: 11.5px; }
    .diff-head span:last-child { display: none; }
    .step { grid-template-columns: 1fr; gap: 4px; }
    .step > span { line-height: 1; }
